<script setup>
import {ref,onMounted,onUnmounted,watch} from 'vue'
import {api} from '../services/api.js'
const nodes=ref([]),groups=ref([]),nodeIds=ref([]),groupId=ref(''),seconds=ref(600),protectedCidrs=ref(''),reason=ref(''),incidentId=ref(''),preview=ref(null),result=ref({items:[],total:0}),page=ref(1),status=ref(''),error=ref(''),busy=ref(false),restoreReasons=ref({})
let timer
const payload=()=>({nodeIds:nodeIds.value,...(groupId.value?{groupId:groupId.value}:{}),seconds:seconds.value,protectedCidrs:protectedCidrs.value.split(/[,\r\n]/).map(x=>x.trim()).filter(Boolean),reason:reason.value,incidentId:incidentId.value})
async function load(){try{result.value=await api('/containments?'+new URLSearchParams({page:page.value,pageSize:25,...(status.value?{status:status.value}:{})}))}catch(e){error.value=e.message}}
async function inspect(){busy.value=true;error.value='';preview.value=null;try{preview.value=await api('/containments/preview',{method:'POST',body:payload()})}catch(e){error.value=e.message}finally{busy.value=false}}
async function start(){busy.value=true;error.value='';try{await api('/containments',{method:'POST',body:payload()});preview.value=null;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function restore(j){busy.value=true;error.value='';try{await api(`/containments/${j.id}/restore`,{method:'POST',body:{reason:restoreReasons.value[j.id]}});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
watch([nodeIds,groupId,seconds,protectedCidrs,reason,incidentId],()=>preview.value=null,{deep:true})
onMounted(async()=>{try{[nodes.value,groups.value]=await Promise.all([api('/nodes'),api('/node-groups')]);await load();timer=setInterval(()=>{if(result.value.items.some(j=>j.status!=='restored'))load()},3000)}catch(e){error.value=e.message}})
onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="panel glass"><div class="panel-title"><h2>Incident containment</h2><button class="button secondary" @click="load">Refresh</button></div><div class="body"><p class="muted">Preview temporary isolation while preserving configured controller, DNS and identity peers. Only explicitly authorized pilot hosts can be changed until controlled live isolation and restore tests pass. SNMP visibility cannot isolate a host.</p><p v-if="error" class="error-msg" role="alert">{{error}}</p><form class="containment-form" @submit.prevent="inspect"><label>Assets<select v-model="nodeIds" multiple aria-label="Containment assets"><option v-for="n in nodes" :key="n.id" :value="n.id">{{n.hostname}} · {{n.ip}}</option></select></label><label>Include node group<select v-model="groupId"><option value="">No group</option><option v-for="g in groups" :key="g.id" :value="g.id">{{g.name}}</option></select></label><label>Duration (seconds)<input v-model.number="seconds" type="number" min="180" max="3600" required></label><label>Additional protected CIDRs<textarea v-model="protectedCidrs" rows="3" placeholder="192.168.1.10/32"></textarea></label><label>Reason<input v-model="reason" maxlength="2000" required></label><label>External incident ID<input v-model="incidentId" maxlength="200"></label><button class="button secondary" :disabled="busy||!nodeIds.length&&!groupId">Preview containment</button></form><template v-if="preview"><h3>Impact and restoration plan</h3><p>{{preview.restoration}}. Protected peers retain their existing access; containment does not bypass another firewall rule.</p><p>Protected CIDRs: {{preview.config.protectedCidrs.join(', ')}}</p><p v-if="!preview.controlCidrs.length" class="error-msg">Verified controller CIDRs have not been configured on the API server.</p><div class="table-wrap"><table><thead><tr><th>Asset</th><th>Transport</th><th>Readiness</th></tr></thead><tbody><tr v-for="t in preview.targets" :key="t.nodeId"><td>{{t.hostname}}</td><td>{{t.transport||'Unknown'}}</td><td>{{t.reason||'Authorized pilot — host prerequisites checked before changes'}}</td></tr></tbody></table></div><button class="button danger" :disabled="busy||!preview.canStart" @click="start">Start temporary containment</button></template><div class="actions"><select v-model="status" aria-label="Containment status" @change="page=1;load()"><option value="">All states</option><option v-for="s in ['queued','active','partial','restoring','restored']" :key="s">{{s}}</option></select></div><article v-for="j in result.items" :key="j.id" class="incident"><h3>{{j.config.incidentId||'Containment'}} · {{j.status}}</h3><p>{{j.config.reason}} · Expires {{new Date(j.expires_at).toLocaleString()}}</p><div class="table-wrap"><table><thead><tr><th>Asset</th><th>Outcome</th><th>Details</th></tr></thead><tbody><tr v-for="t in j.targets" :key="t.node_id"><td>{{nodes.find(n=>n.id===t.node_id)?.hostname||t.node_id}}</td><td>{{t.status}}</td><td>{{t.error||t.snapshot?.phase||'Not started'}}</td></tr></tbody></table></div><div v-if="j.status!=='restored'" class="actions"><input v-model="restoreReasons[j.id]" placeholder="Restoration reason" :aria-label="'Restoration reason '+j.id"><button class="button secondary" :disabled="busy||!restoreReasons[j.id]?.trim()" @click="restore(j)">Restore and verify</button></div></article><p v-if="!result.items.length">No containment jobs.</p><div class="actions"><span>{{result.total}} jobs · Page {{page}}</span><button class="button secondary" :disabled="page===1" @click="page--;load()">Previous</button><button class="button secondary" :disabled="page*25>=result.total" @click="page++;load()">Next</button></div></div></section></template>
<style scoped>.body{padding:16px;min-width:0}.containment-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;align-items:start}.containment-form label{display:grid;gap:6px}.actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:16px 0}.table-wrap{overflow:auto;max-width:100%;margin:12px 0}table{width:100%}td{max-width:50ch;overflow-wrap:anywhere}.incident{border-top:1px solid var(--border);padding:12px 0}p{overflow-wrap:anywhere}@media(max-width:850px){.containment-form{grid-template-columns:1fr}}</style>
